#include <cstdint>
#include <cstdio>
#include <cstring>
#include <map>
#include <string>
#include <utility>
#include <vector>

struct Record { std::uint64_t seq, time; std::uint32_t pid, kind, extra; };
struct Reply { std::uint32_t missed{ 0 }; std::uint64_t lastSeq{ 0 }; std::vector<Record> records; };
enum Kind : std::uint32_t { ProcessStart = 1, ProcessExit = 2, ThreadStart = 3, ThreadExit = 4 };

bool parseReply(const std::uint8_t* data, std::uint32_t length, Reply& out)
{
    if (!data || length < 16) return false;
    std::uint32_t count, missed;
    std::uint64_t last;
    std::memcpy(&count, data, 4);
    std::memcpy(&missed, data + 4, 4);
    std::memcpy(&last, data + 8, 8);
    if (count > (length - 16) / 32) return false;
    Reply r{ missed, last, {} };
    for (std::uint32_t i{ 0 }; i < count; ++i)
    {
        const std::uint8_t* p{ data + 16 + static_cast<std::size_t>(i) * 32 };
        Record rec{};
        std::memcpy(&rec.seq, p, 8); std::memcpy(&rec.time, p + 8, 8); std::memcpy(&rec.pid, p + 16, 4); std::memcpy(&rec.kind, p + 20, 4); std::memcpy(&rec.extra, p + 24, 4);
        if (!r.records.empty() && rec.seq <= r.records.back().seq) return false;
        r.records.push_back(rec);
    }
    if (!r.records.empty() && r.records.back().seq != last) return false;
    out = std::move(r);
    return true;
}

std::string clockTime(std::uint64_t fileTime)
{
    const std::uint64_t ms{ fileTime / 10'000 };
    const std::uint64_t inDay{ ms % 86'400'000 };
    char buffer[16];
    std::snprintf(buffer, sizeof(buffer), "%02llu:%02llu:%02llu.%03llu",
                  static_cast<unsigned long long>(inDay / 3'600'000), static_cast<unsigned long long>(inDay / 60'000 % 60),
                  static_cast<unsigned long long>(inDay / 1000 % 60), static_cast<unsigned long long>(inDay % 1000));
    return buffer;
}

class Viewer
{
public:
    void apply(const Reply& reply)
    {
        if (reply.missed > 0)
        {
            m_lines.push_back({ 0, "[" + std::to_string(reply.missed) + " events lost]" });
            m_lost += reply.missed;
        }
        for (const Record& r : reply.records)
        {
            const std::string t{ clockTime(r.time) };
            std::string line;
            switch (r.kind)
            {
            case ProcessStart: line = t + " start " + std::to_string(r.pid) + " (parent " + std::to_string(r.extra) + ")"; m_starts[r.pid] = r.time; ++m_started; break;
            case ProcessExit:
            {
                line = t + " exit " + std::to_string(r.pid);
                const auto it{ m_starts.find(r.pid) };
                if (it != m_starts.end()) { line += " after " + std::to_string((r.time - it->second) / 10'000) + " ms"; m_starts.erase(it); }
                ++m_exited;
                break;
            }
            case ThreadStart: line = t + " thread start " + std::to_string(r.pid) + "/" + std::to_string(r.extra); ++m_threads; break;
            case ThreadExit: line = t + " thread exit " + std::to_string(r.pid) + "/" + std::to_string(r.extra); break;
            default: line = t + " event " + std::to_string(r.kind) + " for " + std::to_string(r.pid); break;
            }
            m_lines.push_back({ r.pid, line });
        }
        if (reply.lastSeq > m_next) m_next = reply.lastSeq;
    }

    std::uint64_t nextAfter() const { return m_next; }
    void filterPid(std::uint32_t pid) { m_filter = pid; }

    std::vector<std::string> lines() const
    {
        std::vector<std::string> out;
        for (const auto& [pid, text] : m_lines) if (m_filter == 0 || pid == 0 || pid == m_filter) out.push_back(text);
        return out;
    }

    std::string summary() const
    {
        return std::to_string(m_started) + " started, " + std::to_string(m_exited) + " exited, " + std::to_string(m_threads) + " threads, " + std::to_string(m_lost) + " lost";
    }

private:
    std::vector<std::pair<std::uint32_t, std::string>> m_lines;    // pid 0 = always shown
    std::map<std::uint32_t, std::uint64_t> m_starts;
    std::uint64_t m_next{ 0 }, m_lost{ 0 };
    int m_started{ 0 }, m_exited{ 0 }, m_threads{ 0 };
    std::uint32_t m_filter{ 0 };
};

unitTests:
#include <cstring>
using Lines = std::vector<std::string>;
const std::uint64_t day = 133'000'000'000'000'000ULL - 133'000'000'000'000'000ULL % 864'000'000'000ULL;    // a midnight
std::uint64_t at(int h, int m, int s, int ms) { return day + ((((h * 60ULL + m) * 60 + s) * 1000) + ms) * 10'000; }
std::vector<std::uint8_t> reply(std::uint32_t missed, std::uint64_t last, const std::vector<Record>& recs, std::uint32_t countOverride = 0xFFFFFFFF) {
    std::vector<std::uint8_t> b(16 + recs.size() * 32, 0); const std::uint32_t count = countOverride == 0xFFFFFFFF ? static_cast<std::uint32_t>(recs.size()) : countOverride;
    std::memcpy(b.data(), &count, 4); std::memcpy(b.data() + 4, &missed, 4); std::memcpy(b.data() + 8, &last, 8);
    for (std::size_t i = 0; i < recs.size(); ++i) { std::uint8_t* p = b.data() + 16 + i * 32; std::memcpy(p, &recs[i].seq, 8); std::memcpy(p + 8, &recs[i].time, 8); std::memcpy(p + 16, &recs[i].pid, 4); std::memcpy(p + 20, &recs[i].kind, 4); std::memcpy(p + 24, &recs[i].extra, 4); }
    return b;
}
TEST("clock") { CHECK_EQ(clockTime(at(13, 5, 9, 42)), std::string("13:05:09.042")); CHECK_EQ(clockTime(day), std::string("00:00:00.000")); }
TEST("parsing") {
    const std::vector<Record> recs{ { 5, at(1, 0, 0, 0), 100, ProcessStart, 4 }, { 6, at(1, 0, 1, 0), 100, ThreadStart, 7 } };
    auto b = reply(2, 6, recs); Reply r; CHECK(parseReply(b.data(), static_cast<std::uint32_t>(b.size()), r)); CHECK_EQ(r.records.size(), std::size_t{ 2 }); CHECK_EQ(r.records[1].extra, 7u); CHECK_EQ(r.missed, 2u);
    CHECK(!parseReply(b.data(), static_cast<std::uint32_t>(b.size() - 1), r)); CHECK(!parseReply(b.data(), 15, r));
    auto lie = reply(0, 6, recs, 0x08000001u); CHECK(!parseReply(lie.data(), static_cast<std::uint32_t>(lie.size()), r));
    auto wrongLast = reply(0, 9, recs); CHECK(!parseReply(wrongLast.data(), static_cast<std::uint32_t>(wrongLast.size()), r));
    auto backwards = reply(0, 5, { recs[1], recs[0] }); CHECK(!parseReply(backwards.data(), static_cast<std::uint32_t>(backwards.size()), r));
    auto empty = reply(0, 6, {}); CHECK(parseReply(empty.data(), 16, r)); CHECK(r.records.empty()); CHECK_EQ(r.lastSeq, std::uint64_t{ 6 });
}
TEST("lines, lifetimes and resuming") {
    Viewer v; Reply r;
    auto first = reply(0, 3, { { 1, at(9, 0, 0, 0), 100, ProcessStart, 4 }, { 2, at(9, 0, 0, 5), 100, ThreadStart, 101 }, { 3, at(9, 0, 1, 0), 200, ProcessStart, 100 } });
    parseReply(first.data(), static_cast<std::uint32_t>(first.size()), r); v.apply(r); CHECK_EQ(v.nextAfter(), std::uint64_t{ 3 });
    auto second = reply(4, 9, { { 8, at(9, 0, 2, 500), 100, ProcessExit, 0 }, { 9, at(9, 0, 3, 0), 300, ProcessExit, 0 } });
    parseReply(second.data(), static_cast<std::uint32_t>(second.size()), r); v.apply(r);
    CHECK_EQ(v.lines(), (Lines{ "09:00:00.000 start 100 (parent 4)", "09:00:00.005 thread start 100/101", "09:00:01.000 start 200 (parent 100)",
                                "[4 events lost]", "09:00:02.500 exit 100 after 2500 ms", "09:00:03.000 exit 300" }));
    CHECK_EQ(v.nextAfter(), std::uint64_t{ 9 }); CHECK_EQ(v.summary(), std::string("2 started, 2 exited, 1 threads, 4 lost"));
    v.filterPid(100); CHECK_EQ(v.lines(), (Lines{ "09:00:00.000 start 100 (parent 4)", "09:00:00.005 thread start 100/101", "[4 events lost]", "09:00:02.500 exit 100 after 2500 ms" }));
    v.filterPid(0); CHECK_EQ(v.lines().size(), std::size_t{ 6 });
}
TEST("unknown kinds") { Viewer v; Reply r; r.lastSeq = 1; r.records = { { 1, at(0, 0, 0, 1), 42, 9, 0 } }; v.apply(r); CHECK_EQ(v.lines(), (Lines{ "00:00:00.001 event 9 for 42" })); }

